$ErrorActionPreference='Stop'
Import-Module (Join-Path $PSScriptRoot 'Repato.MayaQaWorkflow.psm1') -Force
Import-Module (Join-Path $PSScriptRoot 'Repato.AgentOrchestration.psm1') -Force
$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));$passed=0
function Check([bool]$ok,[string]$name){if(!$ok){throw "FAILED: $name"};$script:passed++}
function Reject([scriptblock]$x,[string]$name){$ok=$false;try{&$x|Out-Null}catch{$ok=$true};Check $ok $name}
function New-BuildCase {
 param([scriptblock]$Runner,[object]$SourceOverride,[string]$TaskOverride,[string]$WorkflowOverride,[switch]$SkipEvidence)
 $store=Join-Path ([IO.Path]::GetTempPath()) ('maya-runner-'+[guid]::NewGuid().ToString('N'));$wt=Join-Path 'C:\Repato-Autonomous\Worktrees' ('test-'+[guid]::NewGuid().ToString('N'));New-Item $store -ItemType Directory -Force|Out-Null
 $commit=(& git -C $root rev-parse HEAD).Trim();& git -C $root worktree add --detach $wt $commit|Out-Null;$b=New-MayaQaBootstrap -StoreRoot $store -QaWorkflowId create-plan-views-v1 -RunId ('run-'+[guid]::NewGuid().ToString('N'));$source=if($SourceOverride){$SourceOverride}else{[pscustomobject]@{RepositoryRoot=$wt;ExpectedSourceCommit=$commit;ProjectRelativePath='Forma.RevitConnector.csproj'}}
 $null=New-MayaQaBuildRequest -StoreRoot $store -TaskId $b.TaskId -WorkflowId $b.WorkflowId -QaWorkflowId create-plan-views-v1 -UserRequest 'Create Plan Views' -SourceBranch current -ProjectPath 'Forma.RevitConnector.csproj' -AuthenticatedBuildSource $source
 $idTask=if($TaskOverride){$TaskOverride}else{$b.TaskId};$idWorkflow=if($WorkflowOverride){$WorkflowOverride}else{$b.WorkflowId}
 try{$result=Invoke-MayaQaBuildExecute -StoreRoot $store -TaskId $idTask -WorkflowId $idWorkflow -QaWorkflowId create-plan-views-v1 -SourceBranch current -ProjectPath 'Forma.RevitConnector.csproj' -AuthenticatedBuildSource $source -BuildProcessRunner $Runner;$w=@((Find-RepatoTask (Read-RepatoTaskStore $store) $b.TaskId).deploymentWorkflows|Where-Object workflowId -eq $b.WorkflowId)[0];[pscustomobject]@{Store=$store;Worktree=$wt;Bootstrap=$b;Commit=$commit;Result=$result;Workflow=$w}}catch{[pscustomobject]@{Store=$store;Worktree=$wt;Bootstrap=$b;Commit=$commit;Error=$_.Exception.Message;Workflow=@((Find-RepatoTask (Read-RepatoTaskStore $store) $b.TaskId).deploymentWorkflows|Where-Object workflowId -eq $b.WorkflowId)[0]}}
}
function Remove-Case($c){if($c.Worktree -and (Test-Path $c.Worktree)){& git -C $root worktree remove --force $c.Worktree 2>$null|Out-Null};if($c.Store){Remove-Item $c.Store -Recurse -Force -ErrorAction SilentlyContinue}}
$artifactRelative='bin\Release\net8.0-windows\Repato.Revit.dll';$manifestRelative='Repato.addin';$invoked=0
try {
 $c=New-BuildCase -Runner {param($p,$r)$script:invoked++;$o=Join-Path $r 'bin\Release\net8.0-windows';New-Item $o -ItemType Directory -Force|Out-Null;Set-Content (Join-Path $o 'Repato.Revit.dll') 'runner artifact';Set-Content (Join-Path $r 'Repato.addin') '<RevitAddIns></RevitAddIns>';[pscustomobject]@{Lines=@('ok');ExitCode=0}};Check ($invoked -eq 1) 'runner invoked';Check ($c.Result.BuildStatus -eq 'succeeded') 'successful runner';$expected=(Get-FileHash (Join-Path $c.Worktree $artifactRelative)).Hash;Check ($c.Workflow.qaBuildEvidence.ArtifactSha256 -eq $expected) 'production artifact hash';Remove-Case $c
 $fake='1'*40;$c=New-BuildCase -Runner {param($p,$r)$o=Join-Path $r 'bin\Release\net8.0-windows';New-Item $o -ItemType Directory -Force|Out-Null;Set-Content (Join-Path $o 'Repato.Revit.dll') 'source commit test';Set-Content (Join-Path $r 'Repato.addin') '<RevitAddIns></RevitAddIns>';[pscustomobject]@{Lines=@();ExitCode=0;SourceCommit=$fake}};Check ($c.Workflow.qaBuildEvidence.SourceCommit -eq $c.Commit) 'runner source commit ignored';Check ($c.Workflow.qaBuildEvidence.SourceCommit -ne $fake) 'fake source commit rejected';Remove-Case $c
 $fakeHash='0'*64;$c=New-BuildCase -Runner {param($p,$r)$o=Join-Path $r 'bin\Release\net8.0-windows';New-Item $o -ItemType Directory -Force|Out-Null;Set-Content (Join-Path $o 'Repato.Revit.dll') 'artifact hash test';Set-Content (Join-Path $r 'Repato.addin') '<RevitAddIns></RevitAddIns>';[pscustomobject]@{Lines=@();ExitCode=0;ArtifactSha256=$fakeHash}};Check ($c.Workflow.qaBuildEvidence.ArtifactSha256 -eq (Get-FileHash (Join-Path $c.Worktree $artifactRelative)).Hash) 'runner artifact hash ignored';Check ($c.Workflow.qaBuildEvidence.ArtifactSha256 -ne $fakeHash) 'fake artifact hash rejected';Remove-Case $c
 foreach($kind in 'nonzero','missing'){$c=New-BuildCase -Runner $(if($kind -eq 'nonzero'){ {param($p,$r)[pscustomobject]@{Lines=@('error');ExitCode=1}} }else{{param($p,$r)[pscustomobject]@{Lines=@();ExitCode=0}}});Check ($c.Error -match 'Release build failed') "$kind rejected";Check ($c.Workflow.qaBuildStatus -ne 'succeeded') "$kind no successful evidence";Remove-Case $c}
 $c=New-BuildCase -Runner {param($p,$r)[pscustomobject]@{Lines=@();ExitCode=0}} -TaskOverride ('wrong-'+[guid]::NewGuid().ToString('N'));Check ([string]::IsNullOrWhiteSpace($c.Error) -eq $false) 'task mismatch rejected';Check ($c.Workflow.qaBuildStatus -ne 'succeeded') 'task mismatch no evidence';Remove-Case $c
 $c=New-BuildCase -Runner {param($p,$r)[pscustomobject]@{Lines=@();ExitCode=0}} -WorkflowOverride ('wrong-'+[guid]::NewGuid().ToString('N'));Check ([string]::IsNullOrWhiteSpace($c.Error) -eq $false) 'workflow mismatch rejected';Check ($c.Workflow.qaBuildStatus -ne 'succeeded') 'workflow mismatch no evidence';Remove-Case $c
 Reject {Resolve-MayaQaAuthenticatedBuildSource ([pscustomobject]@{RepositoryRoot='C:\outside';ExpectedSourceCommit=('a'*40);ProjectRelativePath='Forma.RevitConnector.csproj'})} 'arbitrary root rejected'
 $wt=Join-Path 'C:\Repato-Autonomous\Worktrees' ('test-'+[guid]::NewGuid().ToString('N'));& git -C $root worktree add --detach $wt $commit|Out-Null;try{Reject {Resolve-MayaQaAuthenticatedBuildSource ([pscustomobject]@{RepositoryRoot=$wt;ExpectedSourceCommit=('a'*40);ProjectRelativePath='Forma.RevitConnector.csproj'})} 'head mismatch rejected'}finally{& git -C $root worktree remove --force $wt 2>$null|Out-Null}
 $dirty=Join-Path ([IO.Path]::GetTempPath()) ('maya-dirty-'+[guid]::NewGuid().ToString('N'));$wt=Join-Path 'C:\Repato-Autonomous\Worktrees' ('test-'+[guid]::NewGuid().ToString('N'));$commit=(& git -C $root rev-parse HEAD).Trim();& git -C $root worktree add --detach $wt $commit|Out-Null;Set-Content (Join-Path $wt 'dirty.cs') 'dirty';$source=[pscustomobject]@{RepositoryRoot=$wt;ExpectedSourceCommit=$commit;ProjectRelativePath='Forma.RevitConnector.csproj'};Reject {Get-MayaQaTrustedBuildSourceCommit $wt (Join-Path $wt 'Forma.RevitConnector.csproj')} 'dirty inputs rejected';& git -C $root worktree remove --force $wt 2>$null|Out-Null
 Reject {Resolve-MayaQaAuthenticatedBuildSource ([pscustomobject]@{RepositoryRoot=(Join-Path 'C:\Repato-Autonomous\Worktrees' 'missing');ExpectedSourceCommit=$commit;ProjectRelativePath='..\Forma.RevitConnector.csproj'})} 'project escape rejected'
 $store=Join-Path ([IO.Path]::GetTempPath()) ('maya-direct-'+[guid]::NewGuid().ToString('N'));$b=New-MayaQaBootstrap -StoreRoot $store -QaWorkflowId create-plan-views-v1 -RunId ('run-'+[guid]::NewGuid().ToString('N'));$cand=Join-Path $store 'candidate';New-Item $cand -ItemType Directory|Out-Null;$dll=Join-Path $cand 'Repato.Revit.dll';Set-Content $dll 'candidate';$hash=(Get-FileHash $dll).Hash;Set-Content (Join-Path $cand 'Repato.addin') '<RevitAddIns></RevitAddIns>';@{SourceCommit=$commit;FrozenArtifactSha256=$hash;SupportedQaWorkflows=@('create-plan-views-v1')}|ConvertTo-Json|Set-Content (Join-Path $cand 'release-manifest.json');$null=New-MayaQaBuildRequest -StoreRoot $store -TaskId $b.TaskId -WorkflowId $b.WorkflowId -QaWorkflowId create-plan-views-v1 -UserRequest 'Create Plan Views' -SourceBranch current -ProjectPath 'Forma.RevitConnector.csproj';Reject {Invoke-MayaQaFrozenCandidateEvidence -StoreRoot $store -TaskId $b.TaskId -WorkflowId $b.WorkflowId -QaWorkflowId create-plan-views-v1 -CandidateDirectory $cand -ExpectedSha256 $hash -ExpectedSourceCommit $commit} 'direct frozen adoption rejected';Remove-Item $store -Recurse -Force -ErrorAction SilentlyContinue
 $impl=Get-Content (Join-Path $PSScriptRoot 'Repato.MayaQaWorkflow.psm1') -Raw;Check ($impl -match 'if\(\$BuildProcessRunner\).*dotnet build') 'default build shape preserved';[pscustomobject]@{Status='PASS';AssertionsPassed=$passed;AssertionsFailed=0}|ConvertTo-Json -Compress
}finally{if($c){Remove-Case $c};if($dirty -and (Test-Path $dirty)){Remove-Item $dirty -Recurse -Force -ErrorAction SilentlyContinue}}
